// attachOptions carries optional flags for runAttach. Force is the original
// flag; Review opts the attach into recording the session as an
// agent_review in the checkpoint metadata.
type attachOptions struct {
	Force bool
	// Review, when true, tags the attached session as a review. Skills are
	// resolved inside runAttach after the real agent is known (via session
	// state or transcript auto-detection), not at the cobra layer — the
	// --agent flag's default points at claude-code, which would otherwise
	// make a Gemini session incorrectly look up review.claude-code config.
	Review bool
	// ReviewSkillsOverride, when non-empty, declares which review skills were
	// run. Empty is valid: the session is still tagged as a review, with no
	// structured skills list. Ignored when Review=false.
	ReviewSkillsOverride []string
	// ReviewPromptOverride, when non-empty, is recorded instead of the
	// transcript's first user prompt. Used by `entire review attach` when a
	// pending-review marker has the exact prompt the user was asked to run.
	ReviewPromptOverride string
}

// committedRefs resolves the committed metadata topology.
func (opts attachOptions) committedRefs(ctx context.Context) cpkg.CommittedRefs {
	return cpkg.ResolveCommittedRefs(ctx)
	repo, err := openRepository(ctx)
	if err != nil {
		return nil, fmt.Errorf("not a git repository: %w", err)
	}
	closeOnError := true
	defer func() {
		if closeOnError {
			_ = repo.Close()
		}
	}()

	// FetchBlobsByHash uses `git fetch-pack` for blob SHAs (porcelain
	// `git fetch` fails against partial-clone repos with "did not send all
	// necessary objects"). Falls back to a full metadata-branch fetch if
	// fetch-pack also can't reach the blobs.
	stores, err := checkpoint.Open(ctx, repo, checkpoint.OpenOptions{BlobFetcher: FetchBlobsByHash})
	if err != nil {
		return nil, fmt.Errorf("open checkpoint store: %w", err)
	}
	store := stores.Primary

	lookup := &explainCheckpointLookup{
		repo:  repo,
		store: store,
	}

	committed, err := store.ListCommitted(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to list checkpoints: %w", err)
	}
	lookup.committed = committed
	closeOnError = false
	return lookup, nil
}

// generateCheckpointSummary generates an AI summary for a checkpoint and persists it.
// The summary is generated from the scoped transcript (only this checkpoint's portion),
// not the entire session transcript.
//
// summaryTimeoutSeconds is the per-invocation --summary-timeout-seconds flag
// value (0 = unset). Effective precedence for the deadline: flag > settings >
// package default. See resolveSummaryTimeout for the resolution.
func generateCheckpointSummary(ctx context.Context, w, errW io.Writer, store checkpoint.Writer, checkpointID id.CheckpointID, cpSummary *checkpoint.CheckpointSummary, content *checkpoint.SessionContent, force bool, summaryTimeoutSeconds int) error {
